                // Declarative route-change: resolves to the nearest enclosing router.
                Button.of("Open kitchen sink", () -> {}).navigate("/kitchen")
        )
        // The destination content region → `<main>`.
        .with(AccessibilityRole.of(Roles.MAIN))
        .with(Padding.of(24));
    }
}

